using UnityEngine;

public class MethodWriter : MonoBehaviour
{
    void Start()
    {
        LogMessage("Script started.");
        float dmg = CalculateDamage(10f);
        LogMessage("Damage: " + dmg);
        ResetPosition();
        LogMessage("Position reset to " + transform.position);
    }

    void LogMessage(string message)
    {
        Debug.Log("[INFO] " + message);
    }

    float CalculateDamage(float baseDamage, float multiplier = 1.5f)
    {
        return baseDamage * multiplier;
    }

    void ResetPosition()
    {
        transform.position = Vector3.zero;
    }
}
